namespace sv_abef44d3479d4a358d782e2ce95c8b9f.Services;

public class ValidationError
{
    public string FieldName { get; set; } = string.Empty;
    public string ErrorMessage { get; set; } = string.Empty;
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public List<ValidationError> Errors { get; set; } = new();
}

public interface IAppointmentService
{
    Task<List<string>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctor, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Patel"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        var slots = new List<string>
        {
            "9:00 AM",
            "9:30 AM",
            "10:00 AM",
            "10:30 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        };

        return Task.FromResult(slots);
    }

    public Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = nameof(email),
                ErrorMessage = "Account has outstanding balance"
            });
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.OrdinalIgnoreCase)
            && string.Equals(doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = "doctor",
                ErrorMessage = "Selected doctor does not accept self-pay patients"
            });
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = "timeSlot",
                ErrorMessage = "This slot is no longer available"
            });
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_abef44d3479d4a358d782e2ce95c8b9f.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />

    @* STEP 1 *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(emailError))
            {
                <div class="validation-message">@emailError</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Check Availability
            </button>
        }
    </fieldset>

    @* STEP 2 *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (!string.IsNullOrEmpty(doctorError))
                {
                    <div class="validation-message">@doctorError</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Appointment Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (!string.IsNullOrEmpty(dateError))
                {
                    <div class="validation-message">@dateError</div>
                }
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (!string.IsNullOrEmpty(timeSlotError))
                {
                    <div class="validation-message">@timeSlotError</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="4" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="submit" class="btn btn-success">Book Appointment</button>
            <button type="button" class="btn btn-secondary ms-2" @onclick="GoBackToStep1">Back</button>
        </fieldset>
    }
</EditForm>

@if (isBooked)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext? editContext;
    private ValidationMessageStore? messageStore;

    private bool showStep2;
    private bool isBooked;
    private List<string> doctors = new();
    private List<string> availableSlots = new();

    private string? emailError;
    private string? doctorError;
    private string? timeSlotError;
    private string? dateError;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ClearServerErrors()
    {
        emailError = null;
        doctorError = null;
        timeSlotError = null;
        dateError = null;
    }

    private async Task ProceedToStep2()
    {
        ClearServerErrors();

        // Validate step 1 fields using a temporary EditContext
        var context = new EditContext(Model);
        var isValid = context.Validate();

        // Check only step 1 fields
        var step1Fields = new[] {
            context.Field(nameof(Model.PatientName)),
            context.Field(nameof(Model.Email)),
            context.Field(nameof(Model.Phone)),
            context.Field(nameof(Model.InsuranceProvider))
        };

        var step1Messages = step1Fields
            .SelectMany(f => context.GetValidationMessages(f))
            .ToList();

        if (step1Messages.Any())
        {
            // Re-trigger validation display via the form's own EditContext
            showStep2 = false;
            StateHasChanged();
            return;
        }

        // Call server validation
        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor ?? "", Model.TimeSlot ?? "");

        if (!result.IsValid)
        {
            foreach (var error in result.Errors)
            {
                switch (error.FieldName)
                {
                    case "email":
                        emailError = error.ErrorMessage;
                        break;
                    case "doctor":
                        doctorError = error.ErrorMessage;
                        break;
                    case "timeSlot":
                        timeSlotError = error.ErrorMessage;
                        break;
                }
            }

            // If only step2 errors (doctor/timeSlot), still show step 2
            if (emailError == null)
            {
                showStep2 = true;
            }
            return;
        }

        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, date);
            Model.TimeSlot = null;
        }

        // Clear related server errors when user changes values
        doctorError = null;
        timeSlotError = null;
    }

    private void GoBackToStep1()
    {
        showStep2 = false;
        ClearServerErrors();
    }

    private async Task HandleSubmit()
    {
        ClearServerErrors();

        // Validate date is in the future
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            dateError = "Appointment date must be in the future";
            return;
        }

        // Final server-side validation
        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor ?? "", Model.TimeSlot ?? "");

        if (!result.IsValid)
        {
            foreach (var error in result.Errors)
            {
                switch (error.FieldName)
                {
                    case "email":
                        emailError = error.ErrorMessage;
                        break;
                    case "doctor":
                        doctorError = error.ErrorMessage;
                        break;
                    case "timeSlot":
                        timeSlotError = error.ErrorMessage;
                        break;
                }
            }
            return;
        }

        isBooked = true;
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_abef44d3479d4a358d782e2ce95c8b9f.Models;

public class AppointmentModel
{
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = string.Empty;

    public string? Doctor { get; set; }

    public DateTime? AppointmentDate { get; set; }

    public string? TimeSlot { get; set; }

    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
    public string? ReasonForVisit { get; set; }
}

