@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext? editContext;
    private ValidationMessageStore? messageStore;

    private bool showStep2;
    private bool isBooked;
    private List<string> doctors = new();
    private List<string> availableSlots = new();

    private string? emailError;
    private string? doctorError;
    private string? timeSlotError;
    private string? dateError;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ClearServerErrors()
    {
        emailError = null;
        doctorError = null;
        timeSlotError = null;
        dateError = null;
    }

    private async Task ProceedToStep2()
    {
        ClearServerErrors();

        // Validate step 1 fields using a temporary EditContext
        var context = new EditContext(Model);
        var isValid = context.Validate();

        // Check only step 1 fields
        var step1Fields = new[] {
            context.Field(nameof(Model.PatientName)),
            context.Field(nameof(Model.Email)),
            context.Field(nameof(Model.Phone)),
            context.Field(nameof(Model.InsuranceProvider))
        };

        var step1Messages = step1Fields
            .SelectMany(f => context.GetValidationMessages(f))
            .ToList();

        if (step1Messages.Any())
        {
            // Re-trigger validation display via the form's own EditContext
            showStep2 = false;
            StateHasChanged();
            return;
        }

        // Call server validation
        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor ?? "", Model.TimeSlot ?? "");

        if (!result.IsValid)
        {
            foreach (var error in result.Errors)
            {
                switch (error.FieldName)
                {
                    case "email":
                        emailError = error.ErrorMessage;
                        break;
                    case "doctor":
                        doctorError = error.ErrorMessage;
                        break;
                    case "timeSlot":
                        timeSlotError = error.ErrorMessage;
                        break;
                }
            }

            // If only step2 errors (doctor/timeSlot), still show step 2
            if (emailError == null)
            {
                showStep2 = true;
            }
            return;
        }

        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, date);
            Model.TimeSlot = null;
        }

        // Clear related server errors when user changes values
        doctorError = null;
        timeSlotError = null;
    }

    private void GoBackToStep1()
    {
        showStep2 = false;
        ClearServerErrors();
    }

    private async Task HandleSubmit()
    {
        ClearServerErrors();

        // Validate date is in the future
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            dateError = "Appointment date must be in the future";
            return;
        }

        // Final server-side validation
        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor ?? "", Model.TimeSlot ?? "");

        if (!result.IsValid)
        {
            foreach (var error in result.Errors)
            {
                switch (error.FieldName)
                {
                    case "email":
                        emailError = error.ErrorMessage;
                        break;
                    case "doctor":
                        doctorError = error.ErrorMessage;
                        break;
                    case "timeSlot":
                        timeSlotError = error.ErrorMessage;
                        break;
                }
            }
            return;
        }

        isBooked = true;
    }
}

